import{_ as i,o as t,c as l,a2 as o}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Vite 工程化","description":"Vite 是下一代前端构建工具,基于原生 ESM + esbuild + Rollup,提供极速的开发体验。","frontmatter":{},"headers":[],"relativePath":"工程化/vite/index.md","filePath":"工程化/vite/index.md","lastUpdated":1793930980000}'),a={name:"工程化/vite/index.md"};function r(s,e,n,d,c,u){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="vite-工程化" tabindex="-1">Vite 工程化 <a class="header-anchor" href="#vite-工程化" aria-label="Permalink to &quot;Vite 工程化&quot;">​</a></h1><blockquote><p>Vite 是下一代前端构建工具,基于<strong>原生 ESM + esbuild + Rollup</strong>,提供极速的开发体验。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-vite">Vite 是什么</a> — 解决了什么问题、核心特性、生态定位</li><li><a href="./2-why-fast">为什么启动这么快</a> — 核心原理:原生 ESM + esbuild</li><li><a href="./3-config">vite.config.ts 详解</a> — 完整配置项实战</li><li><a href="./4-deps-prebundle">依赖预构建</a> — esbuild 预构建 CommonJS → ESM</li><li><a href="./5-dual-build">双构建策略</a> — dev 用 esbuild / prod 用 Rollup</li><li><a href="./6-hmr">Vite HMR 原理</a> — 比 Webpack 快的 HMR 实现</li><li><a href="./7-plugin">Vite 插件开发</a> — 钩子机制 + 实战</li><li><a href="./8-vs-webpack">Vite vs Webpack</a> — 全方位对比,何时选哪个</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>Vite 快的原因不是「用了更快的编译器」这么简单,而是<strong>开发期不打包</strong>:浏览器直接加载原生 ESM,按需编译,启动时间与项目大小基本无关。</li><li>三个关键机制:<strong>原生 ESM</strong>(浏览器直接请求模块)、<strong>依赖预构建</strong>(esbuild 把 CJS 依赖打成 ESM,消除瀑布请求)、<strong>双构建</strong>(dev 用 esbuild,prod 用 Rollup 保证产物质量)。</li><li>依赖预构建的两个目的:统一 CJS/ESM 格式、<strong>把上百个零散依赖合并成一个</strong>,减少请求数。</li><li>HMR 快的原因是边界更精确:只更新<strong>具体模块</strong>而不是整个 bundle,借助 ESM 的 <code>import.meta.hot</code> 手动接受更新。</li><li>插件体系基于 <strong>Rollup 插件规范</strong>的钩子(<code>config/configResolved/transform/load</code> 等),和 Vite 特有的 <code>configureServer</code> 配合开发服务器。</li><li>生产环境 Vite 用 Rollup,所以 tree shaking 与产物优化比 esbuild 更彻底。</li><li>面试对比要点:Webpack 是<strong>打包后启动</strong>,Vite 是<strong>先启动再按需编译</strong>;冷启动 vs 热更新的取舍正好相反。</li></ul>',6)])])}const g=i(a,[["render",r]]);export{h as __pageData,g as default};
